// Prebuild step: decodes the base64-committed raster assets back into
// public/. The PNGs themselves are generated by gen-og-icons.mjs (see
// ../../..), because the repo is synced to GitHub through the text-only
// API transport — binaries are stored as base64 text, split into parts
// when they exceed the transport's size budget.
//
//   scripts/assets/og.png.b64(.part-*)               -> public/media/og.png
//   scripts/assets/apple-touch-icon.png.b64(.part-*) -> public/apple-touch-icon.png
//
// To replace either image: encode your PNG (base64 -w0 og.png > file)
// and re-split, or drop the real file straight into public/ and remove
// the matching entry from .gitignore.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const assets = join(root, 'scripts', 'assets');

function readAsset(name) {
  const single = join(assets, name);
  try {
    return readFileSync(single, 'utf8');
  } catch {
    // Concatenate the split parts in order.
    const parts = readdirSync(assets)
      .filter((f) => f.startsWith(`${name}.part-`))
      .sort();
    return parts.map((p) => readFileSync(join(assets, p), 'utf8')).join('');
  }
}

const pairs = [
  ['og.png.b64', 'public/media/og.png'],
  ['apple-touch-icon.png.b64', 'public/apple-touch-icon.png'],
];

for (const [src, dest] of pairs) {
  const bytes = Buffer.from(readAsset(src).trim(), 'base64');
  writeFileSync(join(root, dest), bytes);
}
console.log('decoded raster assets into public/');
